/**
 * TinyFish's goldfish mark.
 *
 * TinyFish ships this mark only as a raster asset, so the official 256x256 PNG is embedded
 * verbatim inside an SVG wrapper to keep the shared `SVGProps<SVGSVGElement>` icon API. The
 * wrapper's viewBox matches the artwork exactly.
 *
 * @see https://www.tinyfish.ai/favicon-for-app/icon0.svg
 */
export function TinyFishIcon(props: SVGProps<SVGSVGElement>) {
  return (
    <svg
      {...props}
      xmlns='http://www.w3.org/2000/svg'
      viewBox='0 0 256 256'
      width='24'
      height='24'
      fill='none'
    >
      <image href={TINYFISH_ICON_PNG_DATA_URI} x='0' y='0' width='256' height='256' />
    </svg>
  )
}

